terraform {
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

resource "google_storage_bucket" "acme_invoices_archive" {
  name                        = "acme-invoices-archive"
  location                    = "asia-south1"
  storage_class               = "STANDARD"
  uniform_bucket_level_access = true

  versioning {
    enabled = true
  }

  labels = {
    environment = "prod"
  }
}

terraform {
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

# Cloud Storage bucket with uniform bucket-level access and public access prevention
resource "google_storage_bucket" "secure_bucket" {
  name          = "secure-storage-bucket-prod-asia-south1"
  location      = "asia-south1"
  storage_class = "STANDARD"

  # Uniform bucket-level access controls access via IAM exclusively
  uniform_bucket_level_access = true

  # Prevents any data from being made publicly accessible
  public_access_prevention = "enforced"

  # Retention mechanism required by organizational policy
  versioning {
    enabled = true
  }

  # Mandatory organizational labels
  labels = {
    environment = "prod"
  }
}

# Terraform configuration for a Google Cloud Storage bucket with a lifecycle rule
# moving objects to NEARLINE storage after 30 days, adhering to organizational policies.

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

resource "google_storage_bucket" "nearline_lifecycle_bucket" {
  name                        = "org-storage-nearline-30d-bucket"
  location                    = "asia-south1" # Standard organizational region (Mumbai)
  storage_class               = "STANDARD"
  uniform_bucket_level_access = true

  # Explicit retention mechanism mandated by organizational policy
  versioning {
    enabled = true
  }

  # Lifecycle rule to transition objects to NEARLINE storage after 30 days
  lifecycle_rule {
    condition {
      age = 30
    }
    action {
      type          = "SetStorageClass"
      storage_class = "NEARLINE"
    }
  }

  # Mandatory organizational labels
  labels = {
    environment = "prod"
  }
}

terraform {
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "europe-west1"
}

variable "bucket_name" {
  type        = string
  description = "Globally unique name for the Cloud Storage bucket."
  default     = "org-coldline-archive-europe-west1"
}

resource "google_storage_bucket" "coldline_bucket" {
  name          = var.bucket_name
  # The requirement explicitly specifies europe-west1, overriding the default asia-south1 policy.
  location      = "europe-west1"
  storage_class = "COLDLINE"

  # Enforce uniform IAM-based access control
  uniform_bucket_level_access = true

  # Satisfies org policy: explicit retention mechanism required for non-scratch buckets
  versioning {
    enabled = true
  }

  # Satisfies org policy: mandatory environment label for ownership and cost tracking
  labels = {
    environment = "prod"
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

# Cloud Storage bucket with a lifecycle rule to automatically delete objects after 90 days
resource "google_storage_bucket" "auto_delete_bucket" {
  name                        = "org-auto-delete-90d-bucket"
  location                    = "asia-south1"
  uniform_bucket_level_access = true

  lifecycle_rule {
    action {
      type = "Delete"
    }
    condition {
      age = 90
    }
  }

  labels = {
    environment = "dev"
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

# VPC Network and Private Services Access connection required for private IP Cloud SQL
resource "google_compute_network" "default" {
  name                    = "sql-vpc-network"
  auto_create_subnetworks = false
}

resource "google_compute_global_address" "private_ip_address" {
  name          = "sql-private-ip-allocation"
  purpose       = "VPC_PEERING"
  address_type  = "INTERNAL"
  prefix_length = 16
  network       = google_compute_network.default.id
  labels = {
    environment = "prod"
  }
}

resource "google_service_networking_connection" "private_vpc_connection" {
  network                 = google_compute_network.default.id
  service                 = "servicenetworking.googleapis.com"
  reserved_peering_ranges = [google_compute_global_address.private_ip_address.name]
}

# Highly available MySQL 8.0 Cloud SQL instance
resource "google_sql_database_instance" "default" {
  name                = "mysql-ha-instance"
  database_version    = "MYSQL_8_0"
  region              = "asia-south1"
  deletion_protection = true

  settings {
    tier              = "db-custom-2-7680"
    availability_type = "REGIONAL"

    backup_configuration {
      enabled            = true
      binary_log_enabled = true
    }

    ip_configuration {
      ipv4_enabled    = false
      private_network = google_compute_network.default.id
    }

    user_labels = {
      environment = "prod"
    }
  }

  depends_on = [google_service_networking_connection.private_vpc_connection]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

# VPC network required for Cloud SQL private IP connectivity
resource "google_compute_network" "default" {
  name                    = "sql-vpc-network"
  auto_create_subnetworks = false
}

# Reserved IP address range for Service Networking (Private Services Access)
resource "google_compute_global_address" "private_ip_range" {
  name          = "sql-private-ip-range"
  purpose       = "VPC_PEERING"
  address_type  = "INTERNAL"
  prefix_length = 16
  network       = google_compute_network.default.id

  labels = {
    environment = "prod"
  }
}

# Private services access connection to Google Managed Services
resource "google_service_networking_connection" "private_vpc_connection" {
  network                 = google_compute_network.default.id
  service                 = "servicenetworking.googleapis.com"
  reserved_peering_ranges = [google_compute_global_address.private_ip_range.name]
}

# PostgreSQL Cloud SQL instance with private IP and deletion protection enabled
resource "google_sql_database_instance" "default" {
  name                = "prod-postgres-instance"
  database_version    = "POSTGRES_15"
  region              = "asia-south1"
  deletion_protection = true

  depends_on = [google_service_networking_connection.private_vpc_connection]

  settings {
    tier              = "db-custom-2-8192"
    availability_type = "REGIONAL"

    user_labels = {
      environment = "prod"
    }

    backup_configuration {
      enabled                        = true
      point_in_time_recovery_enabled = true
    }

    ip_configuration {
      ipv4_enabled                                  = false
      private_network                               = google_compute_network.default.id
      enable_private_path_for_google_cloud_services = true
    }
  }
}

