# Service account for read-only object operations
resource "google_service_account" "bucket_reader" {
  account_id   = "gcs-bucket-reader"
  display_name = "Cloud Storage Bucket Reader Service Account"
  description  = "Service account with read-only access to private storage bucket"
}

# Private Cloud Storage bucket adhering to organizational retention, region, and security policies
resource "google_storage_bucket" "private_bucket" {
  name                        = "private-storage-bucket-asia-south1"
  location                    = "asia-south1"
  uniform_bucket_level_access = true

  # Explicit retention mechanism mandated by policy
  versioning {
    enabled = true
  }

  # Mandatory labeling for cost and ownership tracking
  labels = {
    environment = "prod"
  }
}

# Least-privilege IAM binding: read-only access scoped strictly to the bucket
resource "google_storage_bucket_iam_member" "reader_object_viewer" {
  bucket = google_storage_bucket.private_bucket.name
  role   = "roles/storage.objectViewer"
  member = "serviceAccount:${google_service_account.bucket_reader.email}"
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "google" {
  # Default region compliant with organizational policy
  region = "asia-south1"
}

variable "environment" {
  type        = string
  description = "Target deployment environment (dev, staging, prod)"
  default     = "prod"
}

variable "db_password" {
  type        = string
  description = "Password for the database user appuser (must not be hardcoded)"
  sensitive   = true
}

resource "random_id" "db_name_suffix" {
  byte_length = 4
}

# PostgreSQL Cloud SQL Instance
resource "google_sql_database_instance" "main" {
  name                = "postgres-instance-${random_id.db_name_suffix.hex}"
  database_version    = "POSTGRES_15"
  region              = "asia-south1"
  deletion_protection = true

  settings {
    tier              = "db-custom-2-8192"
    availability_type = "REGIONAL"

    backup_configuration {
      enabled                        = true
      point_in_time_recovery_enabled = true
    }

    ip_configuration {
      # Public access disabled as per organizational security policy
      ipv4_enabled = false
    }

    user_labels = {
      environment = var.environment
    }
  }
}

# Application Database
resource "google_sql_database" "appdb" {
  name     = "appdb"
  instance = google_sql_database_instance.main.name
}

# Application User
resource "google_sql_user" "appuser" {
  name     = "appuser"
  instance = google_sql_database_instance.main.name
  password = var.db_password
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

data "google_project" "current" {}

# VPC Network for the private GKE cluster
resource "google_compute_network" "vpc" {
  name                    = "gke-vpc"
  auto_create_subnetworks = false
}

# Subnet with secondary IP ranges for GKE pods and services (VPC-native cluster)
resource "google_compute_subnetwork" "gke_subnet" {
  name                     = "gke-subnet"
  ip_cidr_range            = "10.10.0.0/20"
  region                   = "asia-south1"
  network                  = google_compute_network.vpc.id
  private_ip_google_access = true

  secondary_ip_range {
    range_name    = "pods"
    ip_cidr_range = "10.20.0.0/16"
  }

  secondary_ip_range {
    range_name    = "services"
    ip_cidr_range = "10.30.0.0/20"
  }
}

# Dedicated least-privilege service account for GKE nodes
resource "google_service_account" "gke_nodes" {
  account_id   = "gke-node-sa"
  display_name = "GKE Node Service Account"
}

# Grant minimum required roles for node operations
resource "google_project_iam_member" "node_log_writer" {
  project = data.google_project.current.project_id
  role    = "roles/logging.logWriter"
  member  = "serviceAccount:${google_service_account.gke_nodes.email}"
}

resource "google_project_iam_member" "node_metric_writer" {
  project = data.google_project.current.project_id
  role    = "roles/monitoring.metricWriter"
  member  = "serviceAccount:${google_service_account.gke_nodes.email}"
}

resource "google_project_iam_member" "node_monitoring_viewer" {
  project = data.google_project.current.project_id
  role    = "roles/monitoring.viewer"
  member  = "serviceAccount:${google_service_account.gke_nodes.email}"
}

# Regional private GKE cluster with Workload Identity
resource "google_container_cluster" "primary" {
  name     = "primary-private-cluster"
  location = "asia-south1"

  network    = google_compute_network.vpc.id
  subnetwork = google_compute_subnetwork.gke_subnet.id

  # Recommended practice: remove default node pool and use separately managed pools
  remove_default_node_pool = true
  initial_node_count       = 1

  ip_allocation_policy {
    cluster_secondary_range_name  = "pods"
    services_secondary_range_name = "services"
  }

  private_cluster_config {
    enable_private_nodes    = true
    enable_private_endpoint = false
    master_ipv4_cidr_block  = "172.16.0.0/28"
  }

  workload_identity_config {
    workload_pool = "${data.google_project.current.project_id}.svc.id.goog"
  }

  release_channel {
    channel = "REGULAR"
  }

  resource_labels = {
    environment = "prod"
  }
}

# Separately managed node pool configured for Workload Identity
resource "google_container_node_pool" "primary_nodes" {
  name       = "primary-node-pool"
  location   = "asia-south1"
  cluster    = google_container_cluster.primary.id
  node_count = 2

  node_config {
    machine_type    = "e2-medium"
    service_account = google_service_account.gke_nodes.email

    oauth_scopes = [
      "https://www.googleapis.com/auth/cloud-platform"
    ]

    # Required for Workload Identity on nodes
    workload_metadata_config {
      mode = "GKE_METADATA"
    }

    labels = {
      environment = "prod"
    }
  }
}

terraform {
  required_providers {
