# Terraform configuration for a custom-mode VPC network

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

# Note: google_compute_network is a global resource and does not support resource labels in GCP Compute API.
resource "google_compute_network" "custom_vpc" {
  name                    = "custom-vpc-network"
  description             = "Custom-mode VPC network with no automatically created subnets"
  auto_create_subnetworks = false
  routing_mode            = "REGIONAL"
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

# Dedicated least-privilege service account for the node pool
resource "google_service_account" "node_pool_sa" {
  account_id   = "main-cluster-node-sa"
  display_name = "Service Account for main-cluster Node Pool"
}

# GKE node pool for existing main-cluster with autoscaling enabled
resource "google_container_node_pool" "primary_nodes" {
  name     = "main-cluster-pool"
  cluster  = "main-cluster"
  location = "asia-south1"

  # Initial node count per zone before autoscaler takes over
  initial_node_count = 1

  autoscaling {
    min_node_count = 1
    max_node_count = 5
  }

  management {
    auto_repair  = true
    auto_upgrade = true
  }

  node_config {
    machine_type    = "e2-medium"
    service_account = google_service_account.node_pool_sa.email

    oauth_scopes = [
      "https://www.googleapis.com/auth/cloud-platform"
    ]

    # Kubernetes node labels
    labels = {
      environment = "prod"
    }

    # GCP resource labels for cost allocation and governance tracking
    resource_labels = {
      environment = "prod"
    }
  }
}

terraform {
