    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

# Note: google_compute_network and google_compute_subnetwork resources do not
# support resource labels in the Google Cloud API / Terraform provider schema.
resource "google_compute_network" "custom_vpc" {
  name                    = "custom-vpc"
  auto_create_subnetworks = false
  description             = "Custom VPC network"
  routing_mode            = "REGIONAL"
}

resource "google_compute_subnetwork" "custom_subnet" {
  name                     = "subnet-asia-south1"
  ip_cidr_range            = "10.10.0.0/24"
  region                   = "asia-south1"
  network                  = google_compute_network.custom_vpc.id
  private_ip_google_access = true
  description              = "Subnet in asia-south1 with private Google access enabled"
}

# Terraform configuration for allowing inbound SSH (TCP port 22) from a specific CIDR block.

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

# Network hosting the firewall rule
resource "google_compute_network" "vpc_network" {
  name                    = "custom-vpc-network"
  auto_create_subnetworks = false
  description             = "VPC network for secure workloads"
}

# Firewall rule allowing TCP 22 ingress strictly from 203.0.113.0/24
# Note: Google Cloud VPC firewall rules (google_compute_firewall) do not support resource labels in the GCP Compute Engine API.
resource "google_compute_firewall" "allow_ssh_restricted" {
  name        = "allow-ssh-restricted"
  network     = google_compute_network.vpc_network.name
  description = "Allow inbound TCP port 22 exclusively from 203.0.113.0/24"
  direction   = "INGRESS"
  priority    = 1000

  allow {
    protocol = "tcp"
    ports    = ["22"]
  }

  source_ranges = ["203.0.113.0/24"]
}

