data "google_project" "current" {}

# Primary Pub/Sub topic
resource "google_pubsub_topic" "main" {
  name = "main-topic"

  labels = {
    environment = "dev"
  }
}

# Dead-letter Pub/Sub topic
resource "google_pubsub_topic" "dead_letter" {
  name = "main-dead-letter-topic"

  labels = {
    environment = "dev"
  }
}

# Grant the Cloud Pub/Sub service account permission to publish to the dead-letter topic
resource "google_pubsub_topic_iam_member" "dead_letter_publisher" {
  project = google_pubsub_topic.dead_letter.project
  topic   = google_pubsub_topic.dead_letter.name
  role    = "roles/pubsub.publisher"
  member  = "serviceAccount:service-${data.google_project.current.number}@gcp-sa-pubsub.iam.gserviceaccount.com"
}

# Note: The Cloud Pub/Sub service account (service-{project_number}@gcp-sa-pubsub.iam.gserviceaccount.com)
# must also have permission to acknowledge messages on the source subscription (roles/pubsub.subscriber).
# Subscription IAM resource documentation is not present in retrieved context, so it is omitted here.

# Subscription configured with dead-letter policy giving up after 5 delivery attempts
resource "google_pubsub_subscription" "main" {
  name  = "main-subscription"
  topic = google_pubsub_topic.main.id

  dead_letter_policy {
    dead_letter_topic     = google_pubsub_topic.dead_letter.id
    max_delivery_attempts = 5
  }

  labels = {
    environment = "dev"
  }

  depends_on = [
    google_pubsub_topic_iam_member.dead_letter_publisher
  ]
}

