  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

variable "bucket_name" {
  type        = string
  description = "Globally unique name for the public static website Cloud Storage bucket"
  default     = "example-static-site-asia-south1"
}

# Cloud Storage bucket configured for static website hosting
resource "google_storage_bucket" "static_website" {
  name     = var.bucket_name
  location = "asia-south1"

  # Enforce uniform bucket-level access per organizational best practices
  uniform_bucket_level_access = true

  # Website configuration for serving index and error documents
  website {
    main_page_suffix = "index.html"
    not_found_page   = "404.html"
  }

  # Retention mechanism required by org policy for non-temporary storage
  versioning {
    enabled = true
  }

  # Mandatory labels for resource tracking
  labels = {
    environment = "prod"
  }
}

# Grant public read access to all users for website hosting as explicitly requested
resource "google_storage_bucket_iam_member" "public_read" {
  bucket = google_storage_bucket.static_website.name
  role   = "roles/storage.objectViewer"
  member = "allUsers"
}

# Terraform configuration for a MySQL Cloud SQL instance with Public IP access
# constrained to the authorized office VPN network per organizational policy.

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

variable "office_network_cidr" {
  type        = string
  description = "The public CIDR block of the office VPN allowed to access the Cloud SQL instance"
  # Default uses RFC 5737 TEST-NET-1 as a non-0.0.0.0/0 placeholder
  default     = "198.51.100.0/24"
}

resource "google_sql_database_instance" "mysql_instance" {
  name                = "mysql-office-access-instance"
  database_version    = "MYSQL_8_0"
  region              = "asia-south1"
  deletion_protection = true

  settings {
    tier              = "db-custom-2-8192"
    availability_type = "REGIONAL"

    # Mandatory organizational labels
    user_labels = {
      environment = "prod"
    }

    # Backup configuration; MySQL requires binary_log_enabled for point-in-time recovery and HA
    backup_configuration {
      enabled            = true
      binary_log_enabled = true
    }

    ip_configuration {
      # Explicitly enabled per requirement to support access from office VPN without Cloud SQL Auth Proxy
      ipv4_enabled = true

      # Restricted to office CIDR to satisfy organizational no-public-ingress (no 0.0.0.0/0) policy
      authorized_networks {
        name  = "office-vpn"
        value = var.office_network_cidr
      }
    }
  }
}

