  name             = "postgres-pitr-instance"
  database_version = "POSTGRES_15"
  region           = "asia-south1"

  # Retention / deletion protection mandated by policy
  deletion_protection = true

  settings {
    tier              = "db-custom-2-8192"
    availability_type = "REGIONAL"

    # Mandatory organizational labeling
    user_labels = {
      environment = "prod"
    }

    # Backup and Point-In-Time Recovery (PITR) configuration
    backup_configuration {
      enabled                        = true
      point_in_time_recovery_enabled = true
      start_time                     = "02:00"
    }

    # Security policy: disable public IPv4 access
    ip_configuration {
      ipv4_enabled    = false
      private_network = var.private_network_id
    }
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

variable "private_network" {
  description = "The VPC network self link or ID for Cloud SQL private IP connectivity."
  type        = string
  default     = "projects/my-project/global/networks/default"
}

resource "google_sql_database_instance" "postgres" {
  name                = "postgres15-instance"
  database_version    = "POSTGRES_15"
  region              = "asia-south1"
  deletion_protection = true

  settings {
    tier              = "db-custom-2-8192"
    edition           = "ENTERPRISE"
    availability_type = "REGIONAL"

    backup_configuration {
      enabled                        = true
      point_in_time_recovery_enabled = true
    }

    ip_configuration {
      ipv4_enabled    = false
      private_network = var.private_network
    }

    user_labels = {
      environment = "prod"
    }
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

data "google_project" "current" {}

# Dedicated service account for GKE nodes adhering to least privilege
resource "google_service_account" "gke_nodes" {
  account_id   = "gke-node-sa"
  display_name = "GKE Node Pool Service Account"
}

# Grant minimal required roles to the node service account
resource "google_project_iam_member" "node_log_writer" {
  project = data.google_project.current.project_id
  role    = "roles/logging.logWriter"
  member  = "serviceAccount:${google_service_account.gke_nodes.email}"
}

resource "google_project_iam_member" "node_metric_writer" {
  project = data.google_project.current.project_id
  role    = "roles/monitoring.metricWriter"
  member  = "serviceAccount:${google_service_account.gke_nodes.email}"
}

resource "google_project_iam_member" "node_monitoring_viewer" {
  project = data.google_project.current.project_id
  role    = "roles/monitoring.viewer"
  member  = "serviceAccount:${google_service_account.gke_nodes.email}"
}

# Regional GKE Cluster in asia-south1
resource "google_container_cluster" "primary" {
  name     = "primary-gke-cluster"
  location = "asia-south1"

  # Remove default node pool and create minimal initial node pool for bootstrapping
  remove_default_node_pool = true
  initial_node_count       = 1

  # VPC-native routing required for private clusters
  ip_allocation_policy {}

  # Enforce private nodes to prevent external IPs from being assigned
  private_cluster_config {
    enable_private_nodes    = true
    enable_private_endpoint = false
    master_ipv4_cidr_block  = "172.16.0.0/28"
  }

  # Enable Workload Identity
  workload_identity_config {
    workload_pool = "${data.google_project.current.project_id}.svc.id.goog"
  }

  release_channel {
    channel = "REGULAR"
  }

  # Mandatory organizational labels
  resource_labels = {
    environment = "prod"
  }
}

# Separately managed node pool with 3 e2-standard-4 nodes
resource "google_container_node_pool" "primary_nodes" {
  name       = "primary-node-pool"
  location   = "asia-south1"
  cluster    = google_container_cluster.primary.name
  node_count = 3

  node_config {
    machine_type = "e2-standard-4"

    # Assign custom service account with cloud-platform scope
    service_account = google_service_account.gke_nodes.email
    oauth_scopes = [
      "https://www.googleapis.com/auth/cloud-platform"
    ]

    labels = {
      environment = "prod"
    }

    # Shielded VM features for enhanced node security
    shielded_instance_config {
      enable_secure_boot          = true
      enable_integrity_monitoring = true
    }
  }
}

