  region = "asia-south1"
}

# Dedicated VPC network for GKE cluster isolation
resource "google_compute_network" "gke_vpc" {
  name                    = "gke-autopilot-vpc"
  auto_create_subnetworks = false
}

# Subnet configured with private Google access and secondary ranges for pods and services
resource "google_compute_subnetwork" "gke_subnet" {
  name                     = "gke-autopilot-subnet"
  region                   = "asia-south1"
  network                  = google_compute_network.gke_vpc.id
  ip_cidr_range            = "10.10.0.0/20"
  private_ip_google_access = true

  secondary_ip_range {
    range_name    = "gke-pods"
    ip_cidr_range = "10.20.0.0/16"
  }

  secondary_ip_range {
    range_name    = "gke-services"
    ip_cidr_range = "10.30.0.0/20"
  }
}

# GKE Autopilot Cluster in asia-south1
resource "google_container_cluster" "autopilot_cluster" {
  name     = "autopilot-cluster"
  location = "asia-south1"

  enable_autopilot = true

  network    = google_compute_network.gke_vpc.id
  subnetwork = google_compute_subnetwork.gke_subnet.id

  ip_allocation_policy {
    cluster_secondary_range_name  = "gke-pods"
    services_secondary_range_name = "gke-services"
  }

  # Ensure nodes are provisioned with private IP addresses (no public IPs)
  private_cluster_config {
    enable_private_nodes    = true
    enable_private_endpoint = false
    master_ipv4_cidr_block  = "172.16.0.0/28"
  }

  # Mandatory organizational labels
  resource_labels = {
    environment = "prod"
  }
}

