  description             = "VPC network hosting secure internal workloads"
}

resource "google_compute_firewall" "allow_ssh_restricted" {
  name        = "allow-ssh-restricted"
  network     = google_compute_network.vpc_network.name
  description = "Allow inbound SSH access strictly from authorized CIDR 203.0.113.0/24"
  direction   = "INGRESS"
  priority    = 1000

  source_ranges = ["203.0.113.0/24"]

  allow {
    protocol = "tcp"
    ports    = ["22"]
  }

  log_config {
    metadata = "INCLUDE_ALL_METADATA"
  }
}

