# Terraform configuration to deploy a Cloud Router and Cloud NAT in asia-south1
# allowing private VMs without external IP addresses to access the internet.

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

# VPC Network hosting the private workloads
# Note: google_compute_network, google_compute_subnetwork, google_compute_router,
# and google_compute_router_nat do not support the 'labels' argument in the GCP API.
resource "google_compute_network" "vpc" {
  name                    = "vpc-asia-south1"
  auto_create_subnetworks = false
}

# Subnetwork for private VMs in the organization's standard region (asia-south1)
resource "google_compute_subnetwork" "subnet" {
  name                     = "subnet-private-asia-south1"
  region                   = "asia-south1"
  ip_cidr_range            = "10.10.0.0/24"
  network                  = google_compute_network.vpc.id
  private_ip_google_access = true
}

# Cloud Router in asia-south1 associated with the VPC network
resource "google_compute_router" "router" {
  name    = "router-asia-south1"
  region  = "asia-south1"
  network = google_compute_network.vpc.id
}

# Cloud NAT service attached to the Cloud Router
resource "google_compute_router_nat" "nat" {
  name                               = "nat-gateway-asia-south1"
  router                             = google_compute_router.router.name
  region                             = google_compute_router.router.region
  nat_ip_allocate_option             = "AUTO_ONLY"
  source_subnetwork_ip_ranges_to_nat = "ALL_SUBNETWORKS_ALL_IP_RANGES"

  log_config {
    enable = true
    filter = "ERRORS_ONLY"
  }
}

