provider "google" {
  region = "asia-south1"
  zone   = "asia-south1-a"
}

# Dedicated service account following least-privilege principles
resource "google_service_account" "vm_sa" {
  account_id   = "web-1-sa"
  display_name = "Service Account for web-1 instance"
}

resource "google_compute_instance" "web_1" {
  name         = "web-1"
  machine_type = "e2-medium"
  zone         = "asia-south1-a"

  # Organisational policy requires an environment label
  labels = {
    environment = "dev"
  }

  boot_disk {
    initialize_params {
      image = "debian-cloud/debian-12"
      labels = {
        environment = "dev"
      }
    }
  }

  network_interface {
    network = "default"
    # No access_config block is specified to prevent assigning a public IP,
    # complying with organisational policy restricting public access.
  }

  service_account {
    email  = google_service_account.vm_sa.email
    scopes = ["cloud-platform"]
  }
}

