# Dedicated service account for the Compute Engine VM (least privilege)
resource "google_service_account" "vm_service_account" {
  account_id   = "internal-vm-sa"
  display_name = "Service Account for Internal Compute VM"
}

# Private VPC network for isolated internal traffic
resource "google_compute_network" "vpc_network" {
  name                    = "internal-vpc"
  auto_create_subnetworks = false
}

# Subnet located in the designated standard region (asia-south1)
resource "google_compute_subnetwork" "subnet" {
  name                     = "internal-subnet-asia-south1"
  region                   = "asia-south1"
  network                  = google_compute_network.vpc_network.id
  ip_cidr_range            = "10.10.1.0/24"
  private_ip_google_access = true
}

# Compute Engine VM with no external IP and running as the dedicated service account
resource "google_compute_instance" "internal_vm" {
  name         = "internal-vm"
  machine_type = "e2-medium"
  zone         = "asia-south1-a"

  labels = {
    environment = "dev"
  }

  boot_disk {
    initialize_params {
      image = "debian-cloud/debian-12"
      labels = {
        environment = "dev"
      }
    }
  }

  # An interface without an access_config block receives only an internal IP
  network_interface {
    network    = google_compute_network.vpc_network.id
    subnetwork = google_compute_subnetwork.subnet.id
  }

  service_account {
    email  = google_service_account.vm_service_account.email
    scopes = ["cloud-platform"]
  }
}

