# Dedicated service account for Cloud Run workload following least-privilege principles
resource "google_service_account" "cloud_run_sa" {
  account_id   = "cloudrun-hello-sa"
  display_name = "Cloud Run Hello Service Account"
}

# Cloud Run v2 Service deployed in asia-south1
resource "google_cloud_run_v2_service" "default" {
  name                = "hello-service"
  location            = "asia-south1"
  deletion_protection = false

  # Restrict ingress to internal traffic per organizational security policy
  ingress = "INGRESS_TRAFFIC_INTERNAL_ONLY"

  labels = {
    environment = "dev"
  }

  template {
    service_account = google_service_account.cloud_run_sa.email

    labels = {
      environment = "dev"
    }

    containers {
      image = "us-docker.pkg.dev/cloudrun/container/hello"
      ports {
        container_port = 8080
      }
    }
  }
}

