# Pub/Sub topic that receives messages from the scheduled job
resource "google_pubsub_topic" "daily_topic" {
  name = "daily-scheduled-topic"

  labels = {
    environment = "prod"
  }
}

# Cloud Scheduler job configured to run every day at 02:00
# Note: google_cloud_scheduler_job does not support resource labels in the GCP API schema.
resource "google_cloud_scheduler_job" "daily_job" {
  name        = "daily-scheduled-job"
  description = "Triggers daily Pub/Sub publication at 02:00"
  schedule    = "0 2 * * *"
  time_zone   = "Asia/Kolkata"
