  bucket = google_storage_bucket.static_website.name
  role   = "roles/storage.objectViewer"
  member = "allUsers"
}

# Terraform configuration for a MySQL Cloud SQL instance configured with a public IP
# to allow direct connectivity from the office VPN.

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

variable "environment" {
  type        = string
  description = "Deployment environment label (e.g., dev, staging, prod)"
  default     = "prod"
}

variable "office_vpn_cidr" {
  type        = string
  description = "Public CIDR block of the office VPN to authorize for direct database access"
  default     = "203.0.113.0/24"
}

resource "google_sql_database_instance" "mysql_instance" {
  name                = "mysql-public-instance"
  region              = "asia-south1"
  database_version    = "MYSQL_8_0"
  deletion_protection = true

  settings {
    tier              = "db-custom-2-8192"
    availability_type = "REGIONAL"

    backup_configuration {
      enabled            = true
      binary_log_enabled = true # Required for MySQL point-in-time recovery and high availability
    }

    ip_configuration {
      # Explicitly enabled per requirement because the office VPN cannot use Cloud SQL Auth Proxy
      ipv4_enabled = true

      # Restricted to the office VPN CIDR to avoid exposing the instance to 0.0.0.0/0
      authorized_networks {
        name  = "office-vpn"
        value = var.office_vpn_cidr
      }
    }

    user_labels = {
      environment = var.environment
    }
  }
}
